/*
 * Modified by Actuna Sp. z o.o.:
 *   FL-B-009: deploy the effective editor default layout of flows and keep it in the flows
 *   P-02: editorTheme.deploy.staleFlows "reload-only" - flows changed elsewhere block the editor
 *   with a dialog whose only action reloads it (no Overwrite, a deploy always carries the revision);
 *   restart on 409 no longer refers to an undefined variable; the conflict dialog no longer fails
 *   when no background update notice was shown; CommonJS export for unit tests
 *   W-4: 409 version_required (deploy.requireRevision) shows a message and the conflict options
 *   without "Ignore & deploy" (review, merge, reload) instead of looping the conflict dialog
 *   Z-15: editor-only instance (editorOnly) - no Start/Stop flows, "Restart flows" disabled
 *   with a hint (R-39)
 *   #22: a deployment that was saved but whose flows did not (all) start (deploy_start_failed,
 *   deploy_stop_failed with a rev) takes over the new revision and marks the changes as deployed;
 *   deploy errors (also restart and start/stop flows) show a readable message built from the
 *   response instead of its raw JSON; the causes of a failed start are listed (RED.deploy.formatStartErrors);
 *   the final result of a start that outlived the response limit (RED.deploy.showStartResult;
 *   a result that arrives before the response of its deployment is kept until then)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

RED.deploy = (function() {

    var deploymentTypes = {
        "full":{img:"red/images/deploy-full-o.svg"},
        "nodes":{img:"red/images/deploy-nodes-o.svg"},
        "flows":{img:"red/images/deploy-flows-o.svg"}
    }

    var ignoreDeployWarnings = {
        unknown: false,
        unusedConfig: false,
        invalid: false
    }

    var deploymentType = "full";

    var deployInflight = false;

    var currentDiff = null;

    var activeBackgroundDeployNotification;

    // editorTheme.deploy.staleFlows "reload-only": the blocking dialog shown once the flows on the
    // server have changed elsewhere (null while not shown) and whether the page is being reloaded from it
    var staleFlowsNotification = null;
    var staleFlowsReloading = false;
    var staleFlowsPolicyWarned = false;

    /**
     * The policy for an editor whose flows are out of date (editorTheme.deploy.staleFlows):
     * "prompt" (default) - the conflict dialog with review, merge and overwrite;
     * "reload-only" - a blocking dialog whose only action reloads the editor.
     * An unknown value falls back to "prompt" with a warning in the browser console.
     * This protects against this editor only - a client of the Admin API can still deploy without
     * the flow revision.
     * @returns {"prompt"|"reload-only"}
     */
    function staleFlowsPolicy() {
        var policy = RED.settings.theme("deploy.staleFlows", "prompt");
        if (policy !== "prompt" && policy !== "reload-only") {
            if (!staleFlowsPolicyWarned) {
                staleFlowsPolicyWarned = true;
                console.warn("Unknown editorTheme.deploy.staleFlows value: " + JSON.stringify(policy) + " - using \"prompt\"");
            }
            return "prompt";
        }
        return policy;
    }
    function isReloadOnly() {
        return staleFlowsPolicy() === "reload-only";
    }

    function changeDeploymentType(type) {
        deploymentType = type;
        $("#red-ui-header-button-deploy-icon").attr("src",deploymentTypes[type].img);
    }

    /**
     * options:
     *   type: "default" - Button with drop-down options - no further customisation available
     *      label: the text to display - default: "Deploy"
     *   type: "simple"  - Button without dropdown. Customisations:
     *      label: the text to display - default: "Deploy"
     *      icon : the icon to use. Null removes the icon. default: "red/images/deploy-full-o.svg"
     */
    function init(options) {
        options = options || {};
        var type = options.type || "default";
        var label = options.label || RED._("deploy.deploy");

        if (type == "default") {
            $('<li><span class="red-ui-deploy-button-group button-group">'+
              '<a id="red-ui-header-button-deploy" class="red-ui-deploy-button disabled" href="#">'+
                '<span class="red-ui-deploy-button-content">'+
                 '<img id="red-ui-header-button-deploy-icon" src="red/images/deploy-full-o.svg" alt=""> '+
                 '<span>'+label+'</span>'+
                '</span>'+
                '<span class="red-ui-deploy-button-spinner hide">'+
                 '<img src="red/images/spin.svg" alt=""/>'+
                '</span>'+
              '</a>'+
              '<a id="red-ui-header-button-deploy-options" class="red-ui-deploy-button" href="#" aria-label="'+RED._('deploy.options')+'"><i class="fa fa-caret-down"></i><i class="fa fa-lock"></i></a>'+
              '</span></li>').prependTo(".red-ui-header-toolbar");
            const mainMenuItems = [
                {id:"deploymenu-item-full",toggle:"deploy-type",icon:"red/images/deploy-full.svg",label:RED._("deploy.full"),sublabel:RED._("deploy.fullDesc"),selected: true, onselect:function(s) { if(s){changeDeploymentType("full")}}},
                {id:"deploymenu-item-flow",toggle:"deploy-type",icon:"red/images/deploy-flows.svg",label:RED._("deploy.modifiedFlows"),sublabel:RED._("deploy.modifiedFlowsDesc"), onselect:function(s) {if(s){changeDeploymentType("flows")}}},
                {id:"deploymenu-item-node",toggle:"deploy-type",icon:"red/images/deploy-nodes.svg",label:RED._("deploy.modifiedNodes"),sublabel:RED._("deploy.modifiedNodesDesc"),onselect:function(s) { if(s){changeDeploymentType("nodes")}}},
                null
            ]
            // Z-15: the flows never run on an editor-only instance
            const editorOnly = RED.settings.editorOnly === true;
            if (RED.settings.runtimeState && RED.settings.runtimeState.ui === true && !editorOnly) {
                mainMenuItems.push({id:"deploymenu-item-runtime-start", icon:"red/images/start.svg",label:RED._("deploy.startFlows"),sublabel:RED._("deploy.startFlowsDesc"),onselect:"core:start-flows", visible:false})
                mainMenuItems.push({id:"deploymenu-item-runtime-stop", icon:"red/images/stop.svg",label:RED._("deploy.stopFlows"),sublabel:RED._("deploy.stopFlowsDesc"),onselect:"core:stop-flows", visible:false})
            }
            mainMenuItems.push({id:"deploymenu-item-reload", icon:"red/images/deploy-reload.svg",label:RED._("deploy.restartFlows"),sublabel:editorOnly ? RED._("deploy.editorOnly") : RED._("deploy.restartFlowsDesc"),onselect:"core:restart-flows",disabled:editorOnly})
            RED.menu.init({id:"red-ui-header-button-deploy-options", options: mainMenuItems });
        } else if (type == "simple") {
            var icon = 'red/images/deploy-full-o.svg';
            if (options.hasOwnProperty('icon')) {
                icon = options.icon;
            }

            $('<li><span class="red-ui-deploy-button-group button-group">'+
              '<a id="red-ui-header-button-deploy" class="red-ui-deploy-button disabled" href="#">'+
                '<span class="red-ui-deploy-button-content">'+
                  (icon?'<img id="red-ui-header-button-deploy-icon" src="'+icon+'" alt=""> ':'')+
                  '<span>'+label+'</span>'+
                '</span>'+
                '<span class="red-ui-deploy-button-spinner hide">'+
                 '<img src="red/images/spin.svg" alt=""/>'+
                '</span>'+
              '</a>'+
              '</span></li>').prependTo(".red-ui-header-toolbar");
        }

        $('#red-ui-header-button-deploy').on("click", function(event) {
            event.preventDefault();
            save();
        });

        RED.actions.add("core:deploy-flows",save);
        if (type === "default") {
            const editorOnly = RED.settings.editorOnly === true;
            if (RED.settings.runtimeState && RED.settings.runtimeState.ui === true && !editorOnly) {
                RED.actions.add("core:stop-flows",function() { stopStartFlows("stop") });
                RED.actions.add("core:start-flows",function() { stopStartFlows("start") });
            }
            if (editorOnly) {
                // Z-15 (R-39): restarting the flows has no effect on an editor-only instance
                RED.actions.add("core:restart-flows",function() {
                    RED.notify(RED._("deploy.editorOnly"), "warning");
                });
            } else {
                RED.actions.add("core:restart-flows",restart);
            }
            RED.actions.add("core:set-deploy-type-to-full",function() { RED.menu.setSelected("deploymenu-item-full",true);});
            RED.actions.add("core:set-deploy-type-to-modified-flows",function() { RED.menu.setSelected("deploymenu-item-flow",true); });
            RED.actions.add("core:set-deploy-type-to-modified-nodes",function() { RED.menu.setSelected("deploymenu-item-node",true); });
        }

        window.addEventListener('beforeunload', function (event) {
            // reloading from the stale flows dialog discards the undeployed changes - the dialog says so
            if (staleFlowsReloading) {
                return;
            }
            if (RED.nodes.dirty()) {
                event.preventDefault();
                event.stopImmediatePropagation()
                event.returnValue = RED._("deploy.confirm.undeployedChanges");
                return
            }
        })

        RED.events.on('workspace:dirty',function(state) {
            if (RED.settings.user?.permissions === 'read') {
                return
            }
            if (staleFlowsNotification) {
                // out of date - only a reload may follow
                $("#red-ui-header-button-deploy").addClass("disabled");
                return
            }
            if (state.dirty) {
                // window.onbeforeunload = function() {
                //     return 
                // }
                $("#red-ui-header-button-deploy").removeClass("disabled");
            } else {
                // window.onbeforeunload = null;
                $("#red-ui-header-button-deploy").addClass("disabled");
            }
        });

        RED.comms.subscribe("notification/runtime-deploy",function(topic,msg) {
            var currentRev = RED.nodes.version();
            if (currentRev === null || deployInflight || currentRev === msg.revision) {
                return;
            }
            if (isReloadOnly()) {
                showStaleFlowsReload();
                return;
            }
            if (activeBackgroundDeployNotification?.hidden && !activeBackgroundDeployNotification?.closed) {
                activeBackgroundDeployNotification.showNotification()
                return
            }
            const message = $('<p>').text(RED._('deploy.confirm.backgroundUpdate'));
            const options = {
                id: 'background-update',
                type: 'compact',
                modal: false,
                fixed: true,
                timeout: 10000,
                buttons: [
                    {
                        text: RED._('deploy.confirm.button.review'),
                        class: "primary",
                        click: function() {
                            activeBackgroundDeployNotification.hideNotification();
                            var nns = RED.nodes.createCompleteNodeSet();
                            resolveConflict(nns,false);
                        }
                    }
                ]
            }
            if (!activeBackgroundDeployNotification || activeBackgroundDeployNotification.closed) {
                activeBackgroundDeployNotification = RED.notify(message, options)
            } else {
                activeBackgroundDeployNotification.update(message, options)
            }
        });


        updateLockedState()
        RED.events.on('login', updateLockedState)
    }

    function updateLockedState() {
        if (!RED.user.hasPermission('flows.write')) {
            $(".red-ui-deploy-button-group").addClass("readOnly");
            $("#red-ui-header-button-deploy").addClass("disabled");
        } else {
            $(".red-ui-deploy-button-group").removeClass("readOnly");
            if (RED.nodes.dirty() && !staleFlowsNotification) {
                $("#red-ui-header-button-deploy").removeClass("disabled");
            }
        }
    }

    function getNodeInfo(node) {
        var tabLabel = "";
        if (node.z) {
            var tab = RED.nodes.workspace(node.z);
            if (!tab) {
                tab = RED.nodes.subflow(node.z);
                tabLabel = tab.name;
            } else {
                tabLabel = tab.label;
            }
        }
        var label = RED.utils.getNodeLabel(node,node.id);
        return {tab:tabLabel,type:node.type,label:label};
    }
    function sortNodeInfo(A,B) {
        if (A.tab < B.tab) { return -1;}
        if (A.tab > B.tab) { return 1;}
        if (A.type < B.type) { return -1;}
        if (A.type > B.type) { return 1;}
        if (A.name < B.name) { return -1;}
        if (A.name > B.name) { return 1;}
        return 0;
    }

    /**
     * Whether a failed deploy request was rejected because the server requires the flow
     * revision (409 version_required, deploy.requireRevision).
     */
    function isVersionRequired(xhr) {
        var body = xhr && xhr.responseJSON;
        if (!body && xhr && xhr.responseText) {
            try {
                body = JSON.parse(xhr.responseText);
            } catch(err) {
                body = null;
            }
        }
        return !!(body && body.code === "version_required");
    }

    /**
     * @param {Array} currentNodes
     * @param {boolean} activeDeploy - offer "Ignore & deploy" (overwrite)
     * @param {Object} [options]
     * @param {boolean} [options.revisionRequired] - the server rejected a deploy without the
     *     revision (409 version_required): no "Ignore & deploy" - it would be rejected again -
     *     but a message and the option to reload the flows
     */
    function resolveConflict(currentNodes, activeDeploy, options) {
        var revisionRequired = !!(options && options.revisionRequired);
        if (revisionRequired) {
            activeDeploy = false;
        }
        var message = $('<div>');
        if (revisionRequired) {
            $('<p>').text(RED._("deploy.errors.revisionRequired")).appendTo(message);
        }
        $('<p data-i18n="deploy.confirm.conflict"></p>').appendTo(message);
        var conflictCheck = $('<div class="red-ui-deploy-dialog-confirm-conflict-row">'+
            '<img src="red/images/spin.svg" alt=""/><div data-i18n="deploy.confirm.conflictChecking"></div>'+
        '</div>').appendTo(message);
        var conflictAutoMerge = $('<div class="red-ui-deploy-dialog-confirm-conflict-row">'+
            '<i class="fa fa-check"></i><div data-i18n="deploy.confirm.conflictAutoMerge"></div>'+
            '</div>').hide().appendTo(message);
        var conflictManualMerge = $('<div class="red-ui-deploy-dialog-confirm-conflict-row">'+
            '<i class="fa fa-exclamation"></i><div data-i18n="deploy.confirm.conflictManualMerge"></div>'+
            '</div>').hide().appendTo(message);

        message.i18n();
        currentDiff = null;
        var buttons = [
            {
                text: RED._("common.label.cancel"),
                click: function() {
                    conflictNotification.close();
                }
            },
            {
                id: "red-ui-deploy-dialog-confirm-deploy-review",
                text: RED._("deploy.confirm.button.review"),
                class: "primary disabled",
                click: function() {
                    if (!$("#red-ui-deploy-dialog-confirm-deploy-review").hasClass('disabled')) {
                        RED.diff.showRemoteDiff(null, {
                            onmerge: function () {
                                activeBackgroundDeployNotification?.close()
                            }
                        });
                        conflictNotification.close();
                    }
                }
            },
            {
                id: "red-ui-deploy-dialog-confirm-deploy-merge",
                text: RED._("deploy.confirm.button.merge"),
                class: "primary disabled",
                click: function() {
                    if (!$("#red-ui-deploy-dialog-confirm-deploy-merge").hasClass('disabled')) {
                        RED.diff.mergeDiff(currentDiff);
                        conflictNotification.close();
                        activeBackgroundDeployNotification?.close()
                    }
                }
            }
        ];
        if (revisionRequired) {
            buttons.push({
                id: "red-ui-deploy-dialog-confirm-deploy-reload",
                text: RED._("deploy.confirm.button.reload"),
                class: "primary",
                click: function() {
                    // the browser asks before undeployed changes are lost
                    window.location.reload();
                }
            })
        }
        if (activeDeploy) {
            buttons.push({
                id: "red-ui-deploy-dialog-confirm-deploy-overwrite",
                text: RED._("deploy.confirm.button.overwrite"),
                class: "primary",
                click: function() {
                    save(true,activeDeploy);
                    conflictNotification.close();
                    activeBackgroundDeployNotification?.close()
                }
            })
        }
        var conflictNotification = RED.notify(message,{
            modal: true,
            fixed: true,
            width: 600,
            buttons: buttons
        });

        RED.diff.getRemoteDiff(function(diff) {
            currentDiff = diff;
            conflictCheck.hide();
            var d = Object.keys(diff.conflicts);
            if (d.length === 0) {
                conflictAutoMerge.show();
                $("#red-ui-deploy-dialog-confirm-deploy-merge").removeClass('disabled')
            } else {
                conflictManualMerge.show();
            }
            $("#red-ui-deploy-dialog-confirm-deploy-review").removeClass('disabled')
        })
    }
    /**
     * editorTheme.deploy.staleFlows "reload-only": the flows on the server have changed since this
     * editor loaded them. A modal dialog that cannot be closed (no Cancel, not closed by Escape or a
     * timeout) whose only action reloads the editor; the deploy button stays disabled until then.
     */
    function showStaleFlowsReload() {
        $("#red-ui-header-button-deploy").addClass("disabled");
        if (staleFlowsNotification) {
            return;
        }
        if (activeBackgroundDeployNotification && !activeBackgroundDeployNotification.closed) {
            activeBackgroundDeployNotification.close();
        }
        var message = $('<div id="red-ui-deploy-dialog-stale-flows">');
        $('<p>').text(RED._("deploy.confirm.staleFlows")).appendTo(message);
        $('<p>').text(RED._("deploy.confirm.staleFlowsLost")).appendTo(message);
        staleFlowsNotification = RED.notify(message, {
            modal: true,
            fixed: true,
            width: 600,
            buttons: [
                {
                    id: "red-ui-deploy-dialog-stale-flows-reload",
                    text: RED._("deploy.confirm.button.reload"),
                    class: "primary",
                    click: function() {
                        staleFlowsReloading = true;
                        $("#red-ui-deploy-dialog-stale-flows-reload").addClass("disabled");
                        window.location.reload();
                    }
                }
            ]
        });
    }

    function cropList(list) {
        if (list.length > 5) {
            var remainder = list.length - 5;
            list = list.slice(0,5);
            list.push(RED._("deploy.confirm.plusNMore",{count:remainder}));
        }
        return list;
    }
    function sanitize(html) {
        // quotes too (#22): a value is safe also inside an attribute of a catalog message
        return html.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")
    }

    // #22: the notification of the last deployment that answered start_timeout, with its revision,
    // and the notification of the final result of a start
    var startTimeoutNotice = null;
    var startResultNotification = null;
    var startResultType = null;
    // the latest result that was ignored because its revision is not (yet) the one of the editor:
    // the event can arrive before the response of the deployment that carries the revision
    var ignoredStartResult = null;

    // #22: errors of a deployment whose configuration is saved although the flows did not (all) start
    var SAVED_DEPLOY_ERRORS = ["deploy_start_failed", "deploy_stop_failed"];

    /**
     * The JSON body of an error response, or null when there is none (no body, not JSON, not an object).
     */
    function parseErrorResponse(xhr) {
        var body = xhr.responseJSON;
        if (body === undefined && xhr.responseText) {
            try {
                body = JSON.parse(xhr.responseText);
            } catch (parseError) {
                // not JSON (for example an error page of a proxy): no structured body
                return null;
            }
        }
        return (body && typeof body === "object" && !Array.isArray(body)) ? body : null;
    }

    /**
     * The revision of a deployment that was saved although the flows did not (all) start
     * (status 500, deploy_start_failed / deploy_stop_failed with a rev), otherwise null.
     */
    function savedRevision(xhr) {
        var body = parseErrorResponse(xhr);
        if (xhr.status === 500 && body && SAVED_DEPLOY_ERRORS.indexOf(body.code) !== -1 && body.rev !== undefined && body.rev !== null) {
            return body.rev;
        }
        return null;
    }

    /**
     * RED._ for a message with HTML in the catalog: the values taken from a response or from
     * the flows are escaped, never inserted as HTML.
     */
    function translateEscaped(key, params) {
        var safe = {};
        Object.keys(params || {}).forEach(function(name) {
            safe[name] = sanitize(String(params[name]));
        });
        return RED._(key, safe);
    }

    function flowLabel(id) {
        id = String(id);
        if (id === "global") {
            return RED._("deploy.errors.globalFlow");
        }
        var ws = RED.nodes.workspace(id);
        return (ws && typeof ws.label === "string" && ws.label) || id;
    }

    // A list taken from a response: anything that is not an array is an empty list
    function asList(value) {
        return Array.isArray(value) ? value : [];
    }

    /**
     * The sentences (HTML, values escaped) that describe one entry of `errors[]` of a failed
     * start, found by `code`; an unknown code shows its message.
     */
    function describeStartError(entry) {
        entry = entry || {};
        var message = entry.message === undefined || entry.message === null ? "" : String(entry.message);
        switch (entry.code) {
            case "flow_start_failed":
                if (entry.flow !== undefined && entry.flow !== null) {
                    return [translateEscaped("deploy.errors.flowStartFailed", { flow: flowLabel(entry.flow), message: message })];
                }
                return [translateEscaped("deploy.errors.flowStartFailedUnknown", { message: message })];
            case "start_timeout": {
                var sentences = [];
                if (typeof entry.timeout === "number") {
                    sentences.push(translateEscaped("deploy.errors.startTimeout", { timeout: entry.timeout / 1000 }));
                } else {
                    sentences.push(RED._("deploy.errors.startTimeoutNoLimit"));
                }
                if (entry.phase === "modules") {
                    sentences.push(RED._("deploy.errors.startPhaseModules"));
                } else if (entry.phase === "flows") {
                    sentences.push(RED._("deploy.errors.startPhaseFlows"));
                }
                if (entry.current !== undefined && entry.current !== null) {
                    sentences.push(translateEscaped("deploy.errors.startCurrent", { flow: flowLabel(entry.current) }));
                }
                if (Array.isArray(entry.pending) && entry.pending.length > 0) {
                    sentences.push(translateEscaped("deploy.errors.startPending", { flows: cropList(entry.pending.map(flowLabel)).join(", ") }));
                }
                sentences.push(RED._("deploy.errors.startResultLater"));
                return sentences;
            }
            case "missing_types":
                return [translateEscaped("deploy.errors.missingTypes", { types: cropList(asList(entry.types).map(String)).join(", ") })];
            case "missing_modules":
                return [translateEscaped("deploy.errors.missingModules", {
                    modules: cropList(asList(entry.modules).map(function(m) { return m && typeof m === "object" ? String(m.module) : String(m) })).join(", ")
                })];
            case "safe_mode":
                return [RED._("deploy.errors.safeMode")];
            default:
                return [sanitize(message || String(entry.code || RED._("deploy.errors.unexpectedEntry")))];
        }
    }

    /**
     * The causes of a failed start as an HTML list (all values escaped), one item per `errors[]`
     * entry. Also used by the notification of the final result of a start (editor-client/src/js/red.js).
     * @param {Array} errors - `errors[]` of the response / of the runtime event
     * @return {String}
     */
    function formatStartErrors(errors) {
        var items = (Array.isArray(errors) ? errors : []).map(function(entry) {
            return "<li>" + describeStartError(entry).join("<br>") + "</li>";
        });
        return '<ul class="red-ui-deploy-dialog-confirm-list">' + items.join("") + "</ul>";
    }

    /**
     * #22: the final result of a start that outlived the response limit of a deployment (the runtime
     * event `deploy-start-result`, called from editor-client/src/js/red.js): a green "flows started"
     * that closes itself, or a red error with the causes that stays until it is closed. A result of
     * another revision than the one of this editor (a newer deployment, another editor) is ignored.
     * The still-open start_timeout error of the same deployment is closed. The text comes from the
     * catalog, never from the event; the causes are escaped.
     * @param {Object} msg - `{type: "success"|"error", revision, errors?, timeout?}`
     */
    function showStartResult(msg) {
        if (!msg || typeof msg !== "object") {
            return;
        }
        var current = RED.nodes.version();
        if (current !== null && current !== undefined && msg.revision !== current) {
            ignoredStartResult = msg;
            return;
        }
        ignoredStartResult = null;
        if (startTimeoutNotice && startTimeoutNotice.rev === msg.revision) {
            if (!startTimeoutNotice.notification.closed) {
                startTimeoutNotice.notification.close();
            }
            startTimeoutNotice = null;
        }
        var success = msg.type === "success";
        var html = RED._(success ? "notification.info.deploy-started" : "notification.errors.deploy-start-failed");
        var options = { type: success ? "success" : "error" };
        var created;
        if (success) {
            options.fixed = false;
            options.timeout = typeof msg.timeout === "number" ? msg.timeout : 8000;
        } else {
            if (Array.isArray(msg.errors) && msg.errors.length > 0) {
                html += formatStartErrors(msg.errors);
            }
            options.fixed = true;
            options.buttons = [
                {
                    text: RED._("common.label.close"),
                    click: function() {
                        created.close();
                    }
                }
            ];
        }
        if (startResultNotification && !startResultNotification.closed && startResultType === options.type) {
            created = startResultNotification;
            startResultNotification.update(html, options);
        } else {
            // another type (a green one would keep the auto-close of a red one): a new notification
            if (startResultNotification && !startResultNotification.closed) {
                startResultNotification.close();
            }
            created = startResultNotification = RED.notify(html, options);
            startResultType = options.type;
        }
    }

    /**
     * Shows the error of a failed deploy / restart / start-stop request: a red notification with a
     * readable message built from the response - never its raw body. A failure with causes
     * (deploy_start_failed, deploy_stop_failed) lists them and stays until it is closed.
     * @param {Object} xhr - the failed request
     * @param {String} messageKey - the message with the `message` parameter for any other error
     * @param {Boolean} saved - the configuration is saved (a deployment, not a restart)
     */
    function notifyDeployFailure(xhr, messageKey, saved) {
        var body = parseErrorResponse(xhr);
        if (body && SAVED_DEPLOY_ERRORS.indexOf(body.code) !== -1) {
            var html;
            if (Array.isArray(body.errors) && body.errors.length > 0) {
                html = formatStartErrors(body.errors);
            } else {
                var detail = typeof body.message === "string" && body.message ? body.message : "";
                var sentence = body.code === "deploy_stop_failed"
                    ? (detail ? translateEscaped("deploy.errors.stopFailedDetail", { message: detail }) : RED._("deploy.errors.stopFailed"))
                    : sanitize(detail || RED._("deploy.errors.unexpectedEntry"));
                html = '<ul class="red-ui-deploy-dialog-confirm-list"><li>' + sentence + "</li></ul>";
            }
            var notification;
            var timedOut = Array.isArray(body.errors) && body.errors.some(function(entry) { return entry && entry.code === "start_timeout" });
            notification = RED.notify("<p>" + RED._(saved ? "deploy.errors.savedWithErrors" : "deploy.errors.startFailed") + "</p>" + html, {
                type: "error",
                fixed: true,
                buttons: [
                    {
                        text: RED._("common.label.close"),
                        click: function() {
                            notification.close();
                        }
                    }
                ]
            });
            if (timedOut && saved) {
                // the final result of this start closes it (showStartResult)
                startTimeoutNotice = { notification: notification, rev: body.rev };
                if (ignoredStartResult && ignoredStartResult.revision === body.rev) {
                    // the result came before this response
                    var early = ignoredStartResult;
                    ignoredStartResult = null;
                    showStartResult(early);
                }
            }
            return;
        }
        var text = body && typeof body.message === "string" && body.message
            ? body.message
            : RED._("deploy.errors.unexpected", { status: xhr.status });
        RED.notify(translateEscaped(messageKey, { message: text }), "error");
    }

    function shadeShow() {
        RED.notifications.shade.show();
    }
    function shadeHide() {
        RED.notifications.shade.hide();
    }
    function deployButtonSetBusy(){
        $(".red-ui-deploy-button-content").css('opacity',0);
        $(".red-ui-deploy-button-spinner").show();
        $("#red-ui-header-button-deploy").addClass("disabled");
    }
    function deployButtonClearBusy(){
        $(".red-ui-deploy-button-content").css('opacity',1);
        $(".red-ui-deploy-button-spinner").hide();
    }
    function stopStartFlows(state) {
        const startTime = Date.now()
        const deployWasEnabled = !$("#red-ui-header-button-deploy").hasClass("disabled")
        deployInflight = true
        deployButtonSetBusy()
        shadeShow()
        $.ajax({
            url:"flows/state",
            type: "POST",
            data: {state: state}
        }).done(function(data,textStatus,xhr) {
            if (deployWasEnabled) {
                $("#red-ui-header-button-deploy").removeClass("disabled")
            }
        }).fail(function(xhr,textStatus,err) {
            if (deployWasEnabled) {
                $("#red-ui-header-button-deploy").removeClass("disabled")
            }
            if (xhr.status === 401) {
                RED.notify(RED._("notification.error", { message: RED._("user.notAuthorized") }), "error")
            } else if (xhr.responseText || xhr.responseJSON) {
                notifyDeployFailure(xhr, "notification.error", false)
            } else {
                RED.notify(RED._("notification.error", { message: RED._("deploy.errors.noResponse") }), "error")
            }
        }).always(function() {
            const delta = Math.max(0, 300 - (Date.now() - startTime))
            setTimeout(function () {
                deployButtonClearBusy()
                shadeHide()
                deployInflight = false
            }, delta);
        });
    }
    function restart() {
        var startTime = Date.now();
        var deployWasEnabled = !$("#red-ui-header-button-deploy").hasClass("disabled");
        deployInflight = true;
        deployButtonSetBusy();
        $.ajax({
            url:"flows",
            type: "POST",
            headers: {
                "Node-RED-Deployment-Type":"reload"
            }
        }).done(function(data,textStatus,xhr) {
            if (deployWasEnabled) {
                $("#red-ui-header-button-deploy").removeClass("disabled");
            }
            RED.notify('<p>'+RED._("deploy.successfulRestart")+'</p>',"success");
        }).fail(function(xhr,textStatus,err) {
            if (deployWasEnabled) {
                $("#red-ui-header-button-deploy").removeClass("disabled");
            }
            if (xhr.status === 401) {
                RED.notify(RED._("deploy.deployFailed",{message:RED._("user.notAuthorized")}),"error");
            } else if (xhr.status === 409) {
                // the node set was an undefined variable here (ReferenceError)
                if (isReloadOnly()) {
                    showStaleFlowsReload();
                } else {
                    resolveConflict(RED.nodes.createCompleteNodeSet(), true);
                }
            } else if (xhr.responseText || xhr.responseJSON) {
                notifyDeployFailure(xhr, "deploy.deployFailed", false);
            } else {
                RED.notify(RED._("deploy.deployFailed",{message:RED._("deploy.errors.noResponse")}),"error");
            }
        }).always(function() {
            var delta = Math.max(0,300-(Date.now()-startTime));
            setTimeout(function() {
                deployButtonClearBusy();
                deployInflight = false;
            },delta);
        });
    }
    /**
     * The changes of the editor are deployed (the configuration is saved on the server):
     * takes over the new revision and clears the changed flags.
     * @param {Array} nns - the node set that was deployed
     * @param {String} rev - the revision of the saved configuration
     */
    function markDeployed(nns, rev) {
        RED.nodes.dirty(false);
        RED.nodes.version(rev);
        RED.nodes.originalFlow(nns);
        // Keep the deployed layout options in the flows so the editor
        // matches what was deployed
        nns.forEach(function (n) {
            const flow = n.type === 'tab' ? RED.nodes.workspace(n.id) : (n.type === 'subflow' ? RED.nodes.subflow(n.id) : null);
            if (flow) {
                ['layout', 'wireStyle'].forEach(function (prop) {
                    if (n[prop] && !flow[prop]) {
                        flow[prop] = n[prop];
                    }
                });
            }
        });
        const flowsToLock = new Set()
        // Node's properties cannot be modified if its workspace is locked.
        function ensureUnlocked(id) {
            // TODO: `RED.nodes.subflow` is useless
            const flow = id && (RED.nodes.workspace(id) || RED.nodes.subflow(id) || null);
            const isLocked = flow ? flow.locked : false;
            if (flow && isLocked) {
                flow.locked = false;
                flowsToLock.add(flow)
            }
        }
        RED.nodes.eachNode(function (node) {
            ensureUnlocked(node.z)
            if (node.changed) {
                node.dirty = true;
                node.changed = false;
            }
            if (node.moved) {
                node.dirty = true;
                node.moved = false;
            }
            if (node.credentials) {
                delete node.credentials;
            }
        });
        RED.nodes.eachGroup(function (node) {
            ensureUnlocked(node.z)
            if (node.changed) {
                node.dirty = true;
                node.changed = false;
            }
            if (node.moved) {
                node.dirty = true;
                node.moved = false;
            }
        })
        RED.nodes.eachJunction(function (node) {
            ensureUnlocked(node.z)
            if (node.changed) {
                node.dirty = true;
                node.changed = false;
            }
            if (node.moved) {
                node.dirty = true;
                node.moved = false;
            }
        })
        RED.nodes.eachConfig(function (confNode) {
            if (confNode.z) {
                ensureUnlocked(confNode.z)
            }
            confNode.changed = false;
            if (confNode.credentials) {
                delete confNode.credentials;
            }
        });
        // Subflow cannot be locked
        RED.nodes.eachSubflow(function (subflow) {
            if (subflow.changed) {
                subflow.changed = false;
                RED.events.emit("subflows:change", subflow);
            }
        });
        RED.nodes.eachWorkspace(function (ws) {
            if (ws.changed || ws.added) {
                // Ensure the Workspace is unlocked to modify its properties.
                ensureUnlocked(ws.id);
                ws.changed = false;
                delete ws.added
                if (flowsToLock.has(ws)) {
                    ws.locked = true;
                    flowsToLock.delete(ws);
                }
                RED.events.emit("flows:change", ws)
            }
        });
        // Ensures all workspaces to be locked have been locked.
        flowsToLock.forEach(flow => {
            flow.locked = true
        })
        // Once deployed, cannot undo back to a clean state
        RED.history.markAllDirty();
        RED.view.redraw();
        RED.sidebar.config.refresh();
        RED.events.emit("deploy");
    }
    function save(skipValidation, force) {
        if (staleFlowsNotification) {
            return; // out of date - only a reload may follow (also for keyboard shortcuts and actions)
        }
        if ($("#red-ui-header-button-deploy").hasClass("disabled")) {
            return; //deploy is disabled
        }
        if ($("#red-ui-header-shade").is(":visible")) {
            return; //deploy is shaded
        }
        if (!RED.user.hasPermission("flows.write")) {
            RED.notify(RED._("user.errors.deploy"), "error");
            return;
        }
        let hasUnusedConfig = false;
        if (!skipValidation) {
            let hasUnknown = false;
            let hasInvalid = false;
            const unknownNodes = [];
            const invalidNodes = [];

            const isDisabled = function (node) {
                return (node.d || RED.nodes.workspace(node.z)?.disabled);
            };

            RED.nodes.eachConfig(function (node) {
                if (node.valid === undefined) {
                    RED.editor.validateNode(node);
                }
                if (!node.valid && !isDisabled(node)) {
                    invalidNodes.push(getNodeInfo(node));
                }
                if (node.type === "unknown") {
                    if (unknownNodes.indexOf(node.name) == -1) {
                        unknownNodes.push(node.name);
                    }
                }
            });
            RED.nodes.eachNode(function (node) {
                if (!node.valid && !isDisabled(node)) {
                    invalidNodes.push(getNodeInfo(node));
                }
                if (node.type === "unknown") {
                    if (unknownNodes.indexOf(node.name) == -1) {
                        unknownNodes.push(node.name);
                    }
                }
            });
            hasUnknown = unknownNodes.length > 0;
            hasInvalid = invalidNodes.length > 0;

            const unusedConfigNodes = [];
            RED.nodes.eachConfig(function (node) {
                if ((node._def.hasUsers !== false) && (node.users.length === 0) && !isDisabled(node)) {
                    unusedConfigNodes.push(getNodeInfo(node));
                    hasUnusedConfig = true;
                }
            });

            let showWarning = false;
            let notificationMessage;
            let notificationButtons = [];
            let notification;
            if (hasUnknown && !ignoreDeployWarnings.unknown) {
                showWarning = true;
                notificationMessage = "<p>" + RED._('deploy.confirm.unknown') + "</p>" +
                    '<ul class="red-ui-deploy-dialog-confirm-list"><li>' + cropList(unknownNodes).map(function (n) { return sanitize(n) }).join("</li><li>") + "</li></ul><p>" +
                    RED._('deploy.confirm.confirm') +
                    "</p>";

                notificationButtons = [
                    {
                        text: RED._("deploy.unknownNodesButton"),
                        class: "pull-left",
                        click: function() {
                            notification.close();
                            RED.actions.invoke("core:search","type:unknown ");
                        }
                    },
                    {
                        id: "red-ui-deploy-dialog-confirm-deploy-deploy",
                        text: RED._("deploy.confirm.button.confirm"),
                        class: "primary",
                        click: function () {
                            save(true);
                            notification.close();
                        }
                    }
                ];
            } else if (hasInvalid && !ignoreDeployWarnings.invalid) {
                showWarning = true;
                invalidNodes.sort(sortNodeInfo);

                notificationMessage = "<p>" + RED._('deploy.confirm.improperlyConfigured') + "</p>" +
                    '<ul class="red-ui-deploy-dialog-confirm-list"><li>' + cropList(invalidNodes.map(function (A) { return sanitize((A.tab ? "[" + A.tab + "] " : "") + A.label + " (" + A.type + ")") })).join("</li><li>") + "</li></ul><p>" +
                    RED._('deploy.confirm.confirm') +
                    "</p>";
                notificationButtons = [
                    {
                        text: RED._("deploy.invalidNodesButton"),
                        class: "pull-left",
                        click: function() {
                            notification.close();
                            RED.actions.invoke("core:search","is:invalid ");
                        }
                    },
                    {
                        id: "red-ui-deploy-dialog-confirm-deploy-deploy",
                        text: RED._("deploy.confirm.button.confirm"),
                        class: "primary",
                        click: function () {
                            save(true);
                            notification.close();
                        }
                    }
                ];
            }
            if (showWarning) {
                notificationButtons.unshift(
                    {
                        text: RED._("common.label.cancel"),
                        click: function () {
                            notification.close();
                        }
                    }
                );
                notification = RED.notify(notificationMessage, {
                    modal: true,
                    fixed: true,
                    buttons: notificationButtons
                });
                return;
            }
        }

        // Flows without their own layout options are deployed with the
        // editor defaults so they look the same for other users
        const nns = RED.nodes.createCompleteNodeSet({ flowLayoutDefaults: true });
        const startTime = Date.now();

        deployButtonSetBusy();
        const data = { flows: nns };
        // "reload-only": a deploy always carries the revision the changes are based on
        if (!force || isReloadOnly()) {
            data.rev = RED.nodes.version();
        }

        deployInflight = true;
        shadeShow();
        $.ajax({
            url: "flows",
            type: "POST",
            data: JSON.stringify(data),
            contentType: "application/json; charset=utf-8",
            headers: {
                "Node-RED-Deployment-Type": deploymentType
            }
        }).done(function (data, textStatus, xhr) {
            markDeployed(nns, data.rev);
            if (hasUnusedConfig) {
                let notification;
                const opts = {
                    type: "success",
                    fixed: false,
                    timeout: 6000,
                    buttons: [
                        {
                            text: RED._("deploy.unusedConfigNodesButton"),
                            class: "pull-left",
                            click: function() {
                                notification.close();
                                RED.actions.invoke("core:search","is:config is:unused ");
                            }
                        },
                        {
                            text: RED._("common.label.close"),
                            class: "primary",
                            click: function () {
                                save(true);
                                notification.close();
                            }
                        }
                    ]
                }
                notification = RED.notify(
                    '<p>' + RED._("deploy.successfulDeploy") + '</p>' +
                    '<p>' + RED._("deploy.unusedConfigNodes") + '</p>', opts);
            } else {
                RED.notify('<p>' + RED._("deploy.successfulDeploy") + '</p>', "success");
            }
        }).fail(function (xhr, textStatus, err) {
            const savedRev = savedRevision(xhr);
            if (savedRev !== null) {
                // #22: the configuration is saved, only the start (or the stop of the previous
                // nodes) failed: the changes are deployed and the next deploy is based on the
                // new revision (no 409)
                markDeployed(nns, savedRev);
            } else {
                RED.nodes.dirty(true);
                $("#red-ui-header-button-deploy").removeClass("disabled");
            }
            if (xhr.status === 401) {
                RED.notify(RED._("deploy.deployFailed", { message: RED._("user.notAuthorized") }), "error");
            } else if (xhr.status === 409) {
                if (isReloadOnly()) {
                    showStaleFlowsReload();
                } else if (isVersionRequired(xhr)) {
                    // W-4: the server requires the revision - "Ignore & deploy" would loop
                    resolveConflict(nns, false, {revisionRequired: true});
                } else {
                    resolveConflict(nns, true);
                }
            } else if (xhr.responseText || xhr.responseJSON) {
                notifyDeployFailure(xhr, "deploy.deployFailed", savedRev !== null);
            } else {
                RED.notify(RED._("deploy.deployFailed", { message: RED._("deploy.errors.noResponse") }), "error");
            }
        }).always(function () {
            const delta = Math.max(0, 300 - (Date.now() - startTime));
            setTimeout(function () {
                deployInflight = false;
                deployButtonClearBusy()
                shadeHide()
            }, delta);
        });
    }
    return {
        init: init,
        setDeployInflight: function(state) {
            deployInflight = state;
        },
        formatStartErrors: formatStartErrors,
        showStartResult: showStartResult

    }
})();

if (typeof module !== "undefined" && module.exports) {
    module.exports = RED.deploy;
}
